const stories = [
{title:'La ley aterriza en Asturias',ref:'LO 7/1981 · 30 de diciembre',pegs:['7 · Ufo','30 · Meru','12 · Tina','19 · Tubo','81 · Chita'],scene:'🛸 → 🐕 → 🛁 → 🦧',text:'Un UFO aterriza sobre Asturias. MERU, tu perra blanca y negra, salta dentro de una TINA. De la tina sale un TUBO gigantesco y por él se desliza CHITA con el Estatuto bajo el brazo.',key:'Ufo = ley orgánica 7. Meru + tina = 30/12. Tubo + Chita = 19–81, el año 1981.',ask:'¿Número, año y fecha de la ley?',answer:'Ley Orgánica 7/1981, de 30 de diciembre.'},
{title:'Una ruta por el Título Preliminar',ref:'Arts. 1–9',pegs:['1 · Tea','2 · Noé','3 · Humo','4 · Oca','5 · Ola','6 · Oso','7 · Ufo','8 · Hacha','9 · Ave'],scene:'🔥 · ⛵ · 🌫 · 🪿 · 🌊 · 🐻 · 🛸 · 🪓 · 🐦',text:'Una TEA ilumina el Estatuto; NOÉ dibuja su territorio. El HUMO pinta una bandera azul y amarilla. Una OCA habla bable por voluntad propia. Una OLA lleva las instituciones a Oviedo. Un OSO ordena concejos, comarcas y parroquias. Un UFO pide DNI español y padrón. Un HACHA talla «asturianía cultural» en una urna cerrada. Un AVE reparte derechos, trabajo, empleo, igualdad y participación.',key:'1 identidad · 2 territorio · 3 símbolos · 4 bable · 5 sede · 6 organización · 7 condición política · 8 asturianía · 9 derechos y objetivos.',ask:'¿Qué artículos separan condición política y asturianía?',answer:'7 y 8. La asturianía del 8 no concede derechos políticos.'},
{title:'El niño de las tres sillas',ref:'Art. 22 · Órganos institucionales',pegs:['22 · Niño'],scene:'🧒 → 🏛 · 👤 · ⚙',text:'Un NIÑO se sienta a la vez en tres sillas gigantes. En la de la JUNTA escribe leyes y presupuestos; en la del PRESIDENTE lleva una corona prestada; en la del CONSEJO DE GOBIERNO mueve las palancas de la Administración.',key:'22 = Niño. Tres sillas = Junta General, Presidente y Consejo de Gobierno. La corona recuerda que el Rey nombra al Presidente; no convierte al Rey en órgano autonómico.',ask:'¿Qué tres órganos enumera el artículo 22?',answer:'Junta General, Consejo de Gobierno y Presidente.'},
{title:'La nuca con un encargo de un solo uso',ref:'Art. 24 bis · Delegación',pegs:['24 · Nuca'],scene:'📜 → ⏳ → 🏗',text:'En una NUCA con un espejo gemelo —«bis»— la Junta escribe un encargo enorme: «EXPRESO, MATERIA CONCRETA, PLAZO». El Consejo construye un texto sobre una BASE; al publicarlo, el encargo se desintegra. Una caja de presupuestos permanece cerrada con candado.',key:'La delegación se agota con la publicación. Ley de bases = articulado; ley ordinaria = refundido. Sin presupuestos, mayorías cualificadas ni subdelegación.',ask:'¿El Consejo puede volver a delegar ese encargo?',answer:'No. El artículo 24 bis prohíbe la subdelegación.'},
{title:'La Junta navega por el Nilo',ref:'Art. 25 · Composición y mandato',pegs:['25 · Nilo','35 · Mula','45 · Celo','4 · Oca'],scene:'🏜 → 🫏 → 🧻 → 🪿',text:'Entre las pirámides del NILO flota una Cámara. Una MULA marca su orilla mínima y una cinta de CELO gigante marca la máxima. Una OCA navega durante cuatro años y coloca una urna en el cuarto domingo de mayo.',key:'Nilo = art. 25. Mula–celo = intervalo 35–45 miembros. Oca = 4 años y cuarto domingo de mayo.',ask:'¿Qué intervalo y duración fija el Estatuto?',answer:'35–45 miembros; cuatro años de mandato ordinario.'},
{title:'Dos temporadas en el centro de la Tierra',ref:'Art. 27 · Sesiones',pegs:['27 · Nife','9 · Ave','12 · Tina','2 · Noé','6 · Oso','4 · Oca'],scene:'🌋 → 🐦🛁 / ⛵🐻',text:'En el NIFE, entre lava, se abre un parlamento con dos puentes. El primero va de un AVE a una TINA; el segundo, de NOÉ a un OSO. Una OCA divide la puerta extraordinaria en cuatro partes y abre una sola.',key:'9→12 = septiembre–diciembre. 2→6 = febrero–junio. Una de cuatro partes = 1/4 de los miembros puede pedir sesión extraordinaria; también Consejo o Diputación Permanente.',ask:'¿Cuáles son los dos períodos ordinarios?',answer:'Septiembre–diciembre y febrero–junio.'},
{title:'La moto imprime en una tela',ref:'Art. 31 · Publicación',pegs:['31 · Moto','15 · Tela'],scene:'🏍 → 🧵 → 📰',text:'Una MOTO lleva al Presidente con un sello del Rey. Al aprobarse la ley, despliega una TELA larguísima que se convierte en un BOPA y empieza una cuenta atrás de quince días. Al lado espera otro periódico con el rótulo BOE.',key:'Moto = 31. Tela = 15 días desde la aprobación para publicar en el BOPA. Promulgación por el Presidente en nombre del Rey; publicación también en BOE.',ask:'¿Desde qué hecho empieza a correr el plazo?',answer:'Desde la aprobación de la ley.'},
{title:'La mina de la investidura',ref:'Art. 32 · 48 horas y 2 meses',pegs:['32 · Mina','48 · Coche','2 · Noé'],scene:'⛏ → 🚗 → ⛵',text:'En una MINA hay una puerta que exige «ABSOLUTA». Si no se abre, un COCHE se queda bloqueado 48 horas antes de llegar a otra puerta que dice «SIMPLE». NOÉ pone dos lunas de calendario sobre el acta de constitución de la Junta; si al cumplirse dos meses nadie sale elegido, desmonta la Cámara.',key:'Mina = 32. Coche = mínimo 48 horas entre convocatorias. Noé = 2 meses desde la constitución. Absoluta primero; simple después.',ask:'¿Desde la primera votación o desde la constitución?',answer:'Desde la constitución de la Junta. El plazo es de dos meses.'},
{title:'La mula de la censura',ref:'Art. 35 · 15 % · 5 días · 2 días · 1 año',pegs:['35 · Mula','15 · Tela','5 · Ola','2 · Noé','1 · Tea'],scene:'🫏 → 🧵 → 🌊 → ⛵ → 🔥',text:'Una MULA trae un candidato sobre una TELA que pone «15 % de firmas». Una OLA bloquea la urna durante cinco días. En los dos primeros, NOÉ trae candidatos alternativos. Si la censura fracasa, una TEA cierra durante un año la puerta de sus firmantes.',key:'15 % propone + candidato; mayoría absoluta aprueba. Espera 5 días; alternativas los 2 primeros; si falla, firmantes esperan 1 año dentro de la misma legislatura.',ask:'¿Qué mayoría aprueba la censura y qué mayoría otorga confianza?',answer:'Censura: absoluta. Confianza: simple.'},
{title:'La tela del relevo sin elecciones',ref:'Art. 35.3 · Confianza denegada',pegs:['15 · Tela'],scene:'👤 → 🧵 → 🏛',text:'El Presidente pierde un puente que se llama CONFIANZA y baja del cargo. El Presidente de la Junta tiende una TELA de quince días para convocar el pleno que elegirá al sucesor. La Cámara permanece atornillada al suelo y una urna electoral sigue guardada.',key:'Dimisión + convocatoria del pleno en máximo 15 días. Convoca el Presidente de la Junta. La pérdida de confianza no disuelve la Junta.',ask:'¿Quién convoca y cuál es el máximo?',answer:'El Presidente de la Junta, en un plazo máximo de quince días.'}
];

const articles = {"1": {"anchor": "aprimero", "paragraphs": ["Uno. Asturias se constituye en Comunidad Autónoma de acuerdo con la Constitución y el presente Estatuto que es su norma institucional básica.", "Dos. La Comunidad Autónoma, comunidad histórica constituida en el ejercicio del derecho al autogobierno amparado por la Constitución, se denomina Principado de Asturias."]}, "2": {"anchor": "asegundo", "paragraphs": ["El territorio del Principado de Asturias es el de los concejos comprendidos dentro de los límites actuales de la provincia de Asturias, para cuya modificación se estará a lo dispuesto en el artículo 56 de este Estatuto."]}, "3": {"anchor": "atercero", "paragraphs": ["Uno. La bandera del Principado de Asturias es la tradicional con la Cruz de la Victoria en amarillo sobre fondo azul.", "Dos. El Principado de Asturias tiene escudo propio y establecerá su himno por Ley del Principado."]}, "4": {"anchor": "acuarto", "paragraphs": ["1. El bable gozará de protección. Se promoverá su uso, su difusión en los medios de comunicación y su enseñanza, respetando en todo caso las variantes locales y la voluntariedad en su aprendizaje.", "2. Una ley del Principado regulará la protección, uso y promoción del bable."]}, "5": {"anchor": "aquinto", "paragraphs": ["La sede de las instituciones del principado de Asturias es la ciudad de Oviedo, sin perjuicio de que por Ley del Principado se establezca alguno de sus organismos, servicios o dependencias en otro lugar del territorio."]}, "6": {"anchor": "asexto", "paragraphs": ["Uno. El Principado de Asturias se organiza territorialmente en municipios, que recibirán la denominación tradicional de Concejos y en Comarcas.", "Dos. Se reconocerá personalidad jurídica a la parroquia rural como forma tradicional de convivencia y asentamiento de la población asturiana.", "Tres. Podrán crearse Áreas Metropolitanas."]}, "7": {"anchor": "aseptimo", "paragraphs": ["Uno. A los efectos del presente Estatuto gozan de la condición política de asturianos los ciudadanos españoles que, de acuerdo con las leyes generales del Estado, tengan vecindad administrativa en cualesquiera de los Concejos de Asturias.", "Dos. Como asturianos, gozan de los derechos políticos definidos en este Estatuto los ciudadanos españoles residentes en el extranjero que hayan tenido la última vecindad administrativa en Asturias y acrediten esta condición en el correspondiente Consulado de España. Gozarán también de estos derechos, si así lo solicitan, sus descendientes inscritos como españoles en la forma que determine la ley del Estado."]}, "8": {"anchor": "aoctavo", "paragraphs": ["Las comunidades asturianas asentadas fuera de Asturias podrán solicitar como tales, el reconocimiento de su asturianía, entendida como el derecho a colaborar y compartir la vida social y cultural de Asturias. Una ley del Principado de Asturias regulará, sin perjuicio de las competencias del Estado, el alcance y contenido de dicho reconocimiento, que en ningún caso implicará la concesión de derechos políticos.", "El Principado de Asturias podrá solicitar del Estado que para facilitar lo dispuesto anteriormente, celebre los oportunos Tratados o Convenios Internacionales con los Estados donde existan dichas comunidades."]}, "9": {"anchor": "anoveno", "paragraphs": ["Uno. Los derechos y deberes fundamentales de los asturianos, son los establecidos en la Constitución.", "Dos. Las instituciones de la Comunidad Autónoma de Asturias, dentro del marco de sus competencias, velarán especialmente por:", "a) Garantizar el adecuado ejercicio de los derechos y deberes fundamentales de cuantos residen en el territorio del Principado.", "b) Impulsar una política tendente a la mejora de las condiciones de vida y trabajo.", "c) Adoptar aquellas medidas que tiendan a fomentar el incremento del empleo y la estabilidad económica.", "d) Procurar la adopción de medidas dirigidas a promover las condiciones y a remover los obstáculos, para que la libertad y la igualdad del individuo y de los grupos en que se integra, sean efectivas y reales.", "e) Facilitar la participación de todos los ciudadanos en la vida política, económica, cultural y social de Asturias."]}, "22": {"anchor": "aveintidos", "paragraphs": ["Los órganos institucionales del Principado de Asturias son la Junta General, el Consejo de Gobierno y el Presidente."]}, "23": {"anchor": "aveintitres", "paragraphs": ["Uno. La Junta General del Principado de Asturias representa al pueblo asturiano, ejerce la potestad legislativa, aprueba los presupuestos, orienta y controla la acción del Consejo de Gobierno y ejerce las restantes competencias que le confiere la Constitución, este Estatuto y demás normas del ordenamiento jurídico.", "Dos. La Junta General es inviolable."]}, "24": {"anchor": "aveinticuatro", "paragraphs": ["Compete también a la Junta General:", "Uno. Elegir de entre sus miembros al Presidente del Principado de Asturias.", "Dos. Designar los Senadores a que se refiere el artículo sesenta y nueve coma cinco, de la Constitución, con arreglo a lo que establezca una ley de la Junta, que asegurará, en todo caso, la adecuada representación proporcional.", "Tres. Ejercitar la iniciativa legislativa según lo dispuesto en la Constitución.", "Cuatro. Fijar las previsiones de índole política, social y económica que, de acuerdo con el artículo ciento treinta y uno coma dos, de la Constitución, haya de suministrar el principado de Asturias al Gobierno para la elaboración de los proyectos de planificación.", "Cinco. Ejercer las competencias atribuidas por el artículo 10.1.2, al Principado de Asturias en lo relativo a la alteración de los términos y denominaciones de los Concejos, así como las facultades en relación a la creación de organizaciones territoriales en los términos establecidos en dicho artículo.", "Seis. Regular la delegación de competencias administrativas del Principado en uno o varios municipios o en las organizaciones territoriales a que se hace referencia en el artículo sexto.", "Siete. Autorizar al Consejo de Gobierno la prestación del consentimiento para obligarse en los convenios y acuerdos del Principado de Asturias con otras Comunidades Autónomas, así como supervisar su ejecución. El Consejo de Gobierno dará cuenta a la Junta General del resto de los convenios y acuerdos que obliguen al Principado.", "Ocho. Establecer tributos. Autorizar el recurso al crédito.", "Nueve. Aprobar el programa del Consejo de Gobierno y exigir su responsabilidad política en la forma que determine una Ley de la Junta.", "Diez. Examinar y aprobar la Cuenta General del Principado, sin perjuicio de lo dispuesto en los artículos 35 ter y 55 de este Estatuto.", "Once. Interponer recursos de inconstitucionalidad y personarse ante el Tribunal Constitucional en los supuestos y términos previstos en la Constitución y en la Ley Orgánica del Tribunal Constitucional.", "Doce. Recibir la información que ha de remitirle el Consejo de Gobierno sobre tratados y convenios internacionales en cuanto se refieran a materias de particular interés para el Principado de Asturias, emitiendo su parecer sobre los mismos."]}, "24 bis": {"anchor": "aveinticuatrobis", "paragraphs": ["1. La Junta General podrá delegar en el Consejo de Gobierno la potestad de dictar normas con rango de ley.", "2. Las disposiciones del Consejo de Gobierno que contengan legislación delegada recibirán el título de Decretos legislativos.", "3. No podrá delegarse la aprobación de la Ley de Presupuestos ni la de normas con rango de ley para las que este Estatuto, las leyes o el Reglamento de la Junta General requieran mayorías cualificadas.", "4. La delegación legislativa habrá de otorgarse al Consejo de Gobierno de forma expresa para materia concreta y con fijación del plazo para su ejercicio. La delegación se agota por el uso que de ella haga el Consejo de Gobierno mediante la publicación de la norma correspondiente. No podrá entenderse concedida de modo implícito o por tiempo indeterminado. Tampoco podrá permitir la subdelegación a autoridades distintas del propio Consejo de Gobierno.", "5. La delegación legislativa deberá otorgarse mediante una ley de bases cuando su objeto sea la formación de textos articulados o por una ley ordinaria cuando se trate de refundir varios textos legales en uno solo.", "6. Las leyes de bases delimitarán con precisión el objeto y alcance de la delegación legislativa y los principios y criterios que han de seguirse en su ejercicio. Las leyes de bases no podrán en ningún caso autorizar su propia modificación ni facultar para dictar normas con carácter retroactivo.", "7. La autorización para refundir textos legales determinará el ámbito normativo a que se refiere el contenido de la delegación, especificando si se circunscribe a la mera formulación de un texto único o si se incluye la de regularizar, aclarar y armonizar los textos legales que han de ser refundidos.", "8. Cuando una proposición de ley o una enmienda fuere contraria a la delegación legislativa en vigor, el Consejo de Gobierno está facultado para oponerse a su tramitación. En tal supuesto, podrá presentarse una proposición de ley para la derogación total o parcial de la ley de delegación.", "9. Sin perjuicio del control jurisdiccional, el Reglamento de la Junta General y las leyes de delegación podrán establecer fórmulas adicionales de control."]}, "25": {"anchor": "aveinticinco", "paragraphs": ["1. La Junta General es elegida por un período de cuatro años mediante sufragio universal, libre, igual, directo y secreto, con aplicación de un sistema de representación proporcional.", "2. Por ley del Principado, cuya aprobación y reforma requiere el voto de la mayoría absoluta de la Junta General, se fijará el número de miembros, entre 35 y 45, sus causas de inelegibilidad e incompatibilidad y las demás circunstancias del procedimiento electoral.", "3. El Presidente del Principado, previa deliberación del Consejo de Gobierno y bajo su exclusiva responsabilidad, podrá acordar la disolución de la Cámara, con anticipación al término natural de la legislatura.", "La disolución se acordará por Decreto, en el que se convocarán a su vez elecciones, conteniéndose en el mismo cuantos requisitos exija la legislación electoral aplicable.", "El Presidente no podrá acordar la disolución de la Cámara durante el primer período de sesiones de la legislatura, cuando reste menos de un año para su terminación, ni cuando se encuentre en tramitación una moción de censura. Tampoco podrá acordar la disolución antes de que transcurra el plazo de un año desde la última disolución por este procedimiento.", "En ningún supuesto podrá el Presidente disolver la Cámara cuando se encuentre convocado un proceso electoral estatal.", "En todo caso, la nueva Cámara que resulte de la convocatoria electoral tendrá un mandato limitado por el término natural de la legislatura originaria.", "4. Las elecciones serán convocadas por el Presidente del Principado en los términos previstos en la Ley de Régimen Electoral General, de manera que se celebren el cuarto domingo de mayo de cada cuatro años, sin perjuicio de lo que dispongan las Cortes Generales, con el fin exclusivo de coordinar el calendario de las diversas consultas electorales.", "5. La Junta General electa será convocada por el Presidente del Principado cesante, dentro de los quince días siguientes a la celebración de las elecciones.", ""]}, "26": {"anchor": "aveintiseis", "paragraphs": ["Los miembros de la Junta General del Principado:", "Uno. No están vinculados por mandato imperativo.", "Dos. Gozarán, aún después de haber cesado en su mandato de inviolabilidad por las opiniones manifestadas en actos parlamentarios y por los votos emitidos en el ejercicio de su cargo. Durante su mandato no podrán ser detenidos ni retenidos por los actos delictivos cometidos en el territorio de Asturias, sino en caso de flagrante delito, correspondiendo decidir en todo caso sobre su inculpación, prisión, procesamiento y juicio al Tribunal Superior de Justicia de la Comunidad Autónoma. Fuera de dicho territorio la responsabilidad penal será exigible, en los mismos términos, ante la Sala de lo Penal del Tribunal Supremo.", "Tres. Tienen derecho a formular preguntas, interpelaciones y mociones en los términos en que el Reglamento determine. También les asiste el derecho a obtener de las autoridades de la Comunidad Autónoma la información precisa para el desarrollo de sus funciones.", "Cuatro. Por el ejercicio de su cargo representativo, los Diputados de la Junta General percibirán retribuciones. Las modalidades de las asignaciones serán fijadas de acuerdo con lo que prevea el Reglamento de la Cámara."]}, "27": {"anchor": "aveintisiete", "paragraphs": ["Uno. La Junta General se reunirá anualmente en dos períodos de sesiones, comprendidos entre septiembre y diciembre el primero, y entre febrero y junio el segundo.", "Dos. A petición del Consejo de Gobierno, de la Diputación Permanente o de la cuarta parte de los miembros de la Junta, ésta podrá reunirse en sesión extraordinaria, que se clausurará al agotar el orden del día determinado para el que fue convocada.", "Tres. Las sesiones plenarias de la Junta son públicas, salvo en los casos previstos en el Reglamento.", "Cuatro. Para la deliberación y adopción de acuerdos, la Junta ha de estar reunida reglamentariamente y con asistencia de la mayoría de sus miembros. Los acuerdos se adoptan por mayoría de los presentes si el Estatuto, las Leyes o el Reglamento no exigen otras mayorías más cualificadas.", "Cinco. El voto es personal y no delegable."]}, "28": {"anchor": "aveintiocho", "paragraphs": ["Uno. La Junta General aprueba su Presupuesto y el estatuto de su personal, y establece su propio Reglamento, en el que se contendrá, además, el estatuto de sus miembros. La aprobación del Reglamento y su reforma precisarán el voto favorable de la mayoría absoluta.", "Dos. La Junta, en su primera sesión, elige su Presidente y demás componentes de la Mesa, que no podrán ser en ningún caso miembros del Consejo de Gobierno ni Presidente del mismo."]}, "29": {"anchor": "aveintinueve", "paragraphs": ["Uno. La Junta General del Principado funciona en Pleno y en Comisiones.", "Dos. Las Comisiones son permanentes y, en su caso, especiales o de investigación.", "Tres. Mientras la Junta General del Principado no esté reunida o cuando hubiere expirado su mandato, habrá una Diputación Permanente, cuyo procedimiento de elección, composición y funciones regulará el Reglamento."]}, "30": {"anchor": "atreinta", "paragraphs": ["Los componentes de la Junta se constituyen en Grupos, cuyas condiciones de formación, organización y funciones fijará el Reglamento. Todo miembro de la Cámara deberá estar adscrito a un Grupo y se garantizará la presencia de cada uno de éstos en las Comisiones y Diputación Permanente en proporción a su importancia numérica."]}, "31": {"anchor": "atreintayuno", "paragraphs": ["1. La iniciativa para el ejercicio de la potestad legislativa reconocida en el artículo 23 de este Estatuto corresponde a los miembros de la Junta General y al Consejo de Gobierno. Por ley del Principado se regulará la iniciativa de los Ayuntamientos y la iniciativa popular para las materias que sean competencia exclusiva de la Comunidad Autónoma.", "2. Las leyes aprobadas por la Junta General serán promulgadas, en nombre del Rey, por el Presidente del Principado, que dispondrá su publicación en el \"Boletín Oficial del Principado de Asturias\", en el plazo de quince días desde su aprobación, y en el \"Boletín Oficial del Estado\". Los Reglamentos serán publicados por orden del Presidente del Principado, dentro del mismo plazo, en el \"Boletín Oficial del Principado de Asturias\"."]}, "32": {"anchor": "atreintaydos", "paragraphs": ["Uno. El Presidente del Principado de Asturias será elegido por la Junta General de entre sus miembros y nombrado por el Rey.", "La elección se hará por mayoría absoluta de los miembros de la Junta en primera convocatoria, y por mayoría simple en las posteriores, debiendo mediar entre cada convocatoria al menos cuarenta y ocho horas.", "Si transcurrido el plazo de dos meses a partir de la constitución de la Junta ningún candidato hubiera sido elegido, la Junta General electa quedará disuelta, procediéndose a la convocatoria de nuevas elecciones. El mandato de la nueva Junta durará en todo caso hasta la fecha en que debiera concluir el de la primera.", "Dos. El Presidente del Principado de Asturias es el del Consejo de Gobierno, cuya actividad dirige, coordina la administración de la Comunidad Autónoma, designa y separa a los consejeros y ostenta la suprema representación del Principado y la ordinaria del Estado en Asturias.", "Tres. El Presidente del Principado de Asturias responde políticamente ante la Junta General.", "Cuatro. Una ley del Principado, aprobada por el voto favorable de la mayoría absoluta, determinará el estatuto personal, el procedimiento de elección y cese y las atribuciones del Presidente."]}, "33": {"anchor": "atreintaytres", "paragraphs": ["Uno. El Consejo de Gobierno es el órgano colegiado que dirige la política de la Comunidad Autónoma y al que corresponden las funciones ejecutiva y administrativa y el ejercicio de la potestad reglamentaria.", "Dos. Por ley del Principado, aprobada por mayoría absoluta, se regularán las atribuciones del Consejo de Gobierno, así como el Estatuto, forma de nombramiento y cese de sus componentes.", "Tres. Una ley de la Junta regulará al régimen de publicación de las normas y publicidad de las disposiciones y actos emanados del Consejo de Gobierno y de la Administración del Principado de Asturias.", "Cuatro. El Consejo de Gobierno será informado de los convenios y tratados internacionales que puedan afectar a materias de su específico interés."]}, "34": {"anchor": "atreintaycuatro", "paragraphs": ["Uno. El Consejo de Gobierno responde políticamente ante la Junta General de forma solidaria, sin perjuicio de la responsabilidad directa de cada uno de sus miembros por su gestión.", "Dos. Una ley de la Junta, aprobada por el voto favorable de la mayoría de sus miembros, regulará la responsabilidad establecida en el número anterior y, en general, las relaciones entre dicha Junta y el Consejo."]}, "35": {"anchor": "atreintaycinco", "paragraphs": ["Uno. El Presidente del Consejo de Gobierno previa deliberación del mismo puede plantear ante la Junta General la cuestión de confianza sobre su programa o sobre una declaración de política general en el marco de las competencias que se atribuyen al Principado en este Estatuto. La confianza se entenderá otorgada cuando vote a favor de la misma la mayoría simple de los miembros de la Junta.", "Dos. La Junta General puede exigir la responsabilidad política del Consejo de Gobierno mediante la adopción por mayoría absoluta de la moción de censura. Esta habrá de ser propuesta al menos por un quince por ciento de los miembros de la Junta y habrá de incluir un candidato a Presidente del Principado de Asturias. La moción de censura no podrá ser votada hasta que transcurran cinco días desde su presentación. En los dos primeros días de dicho plazo podrán presentarse mociones alternativas. Si la moción de censura no fuese aprobada por la Junta General, sus signatarios no podrán presentar otras mientras no transcurra un año desde aquélla dentro de la misma legislatura.", "Tres. Si la Junta General negara su confianza, el Presidente del Principado presentará su dimisión ante la misma, cuyo Presidente convocará en el plazo máximo de quince días la sesión plenaria para la elección de nuevo Presidente del Principado de acuerdo con el procedimiento del artículo treinta y dos coma uno sin que en ningún caso suponga la disolución de la Junta General.", "Cuatro. Si la Junta General adoptara una moción de censura, el Presidente del Principado presentará su dimisión ante la misma y el candidato incluido en aquélla se entenderá investido de la confianza de la Junta. El Rey le nombrará Presidente del Principado.", "Cinco. El Presidente del Principado no podrá plantear la cuestión de confianza mientras esté en trámite una moción de censura.", "Seis. El Consejo de Gobierno cesante continuará en sus funciones hasta la toma de posesión del nuevo Consejo."]}, "35 bis": {"anchor": "atreintaycincobis", "paragraphs": ["1. La responsabilidad penal del Presidente del Principado y de los miembros del Consejo de Gobierno será exigible ante el Tribunal Superior de Justicia del Principado de Asturias por los actos cometidos en el territorio del Principado. Fuera de éste, la responsabilidad penal será exigible ante la Sala de lo Penal del Tribunal Supremo.", "2. Ante los mismos Tribunales respectivamente será exigible la responsabilidad civil en que dichas personas hubieren incurrido con ocasión del ejercicio de sus cargos."]}, "35 ter": {"anchor": "atreintaycincoter.", "paragraphs": ["1. Se crea la Sindicatura de Cuentas del Principado de Asturias. Por ley del Principado se regulará su composición y funciones.", "2. Dependerá directamente de la Junta General del Principado y ejercerá sus funciones por delegación de ella en el examen y comprobación de la Cuenta General del Principado."]}, "35 quater": {"anchor": "atreintaycincoquater.", "paragraphs": ["Se crea el Consejo Consultivo del Principado de Asturias como superior órgano de consulta de la Comunidad Autónoma. Por ley del Principado se regularán su composición y competencias."]}};
const sourcePages=[37,38,42,43,44,45,46,47];
const pageLabels=['Arts. 1–9','Final del art. 9','Arts. 22–24','Arts. 24–25','Arts. 25–27','Arts. 28–32','Arts. 33–35 bis','35 bis y órganos auxiliares'];
const groups={all:'Todo el apartado',preliminar:'Título Preliminar',junta:'Junta General',presidente:'Presidente',gobierno:'Consejo y responsabilidad',anexo:'Complemento: auxiliares'};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=s=>s.replace(/<[^>]*>/g,' ');const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const shuffled=a=>{const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]]}return r};
const key='cuaderno-estatuto-v1';let storageOK=true;let saved={done:[],srs:{},lastWrong:[],lastResult:null};
try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw&&typeof raw==='object'){saved.done=Array.isArray(raw.done)?raw.done.filter(id=>blocks.some(b=>b.id===id&&b.group!=='anexo')):[];saved.srs=raw.srs&&typeof raw.srs==='object'?raw.srs:{};saved.lastWrong=Array.isArray(raw.lastWrong)?raw.lastWrong.filter(i=>Number.isInteger(i)&&questions[i]):[];saved.lastResult=raw.lastResult||null}}catch{storageOK=false}
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));storageOK=true}catch{storageOK=false}$('#storageStatus').textContent=storageOK?'Progreso guardado en este navegador.':'El navegador no permite guardar el progreso. Puedes seguir estudiando durante esta sesión.'}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2800)}
function refButton(ref,label){return `<button class="text-btn" data-article="${esc(ref)}">${esc(label||'Art. '+ref)}</button>`}
function selectOptions(includeAnnex=false){return Object.entries(groups).filter(([k])=>includeAnnex||k!=='anexo').map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}
$('#studyGroup').innerHTML=selectOptions(true);$('#flashGroup').innerHTML=selectOptions();$('#quizGroup').innerHTML=selectOptions();
const cards=blocks.flatMap(b=>b.cards.map((c,i)=>({id:b.id+'-'+i,group:b.group,q:c[0],a:c[1],ref:c[2]})));
$('#cardCountBadge').textContent=cards.length+' tarjetas';
const calendar=()=>`<div class="visual"><h3>Calendario de sesiones ordinarias · Art. 27</h3><div class="months">${['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'].map((m,i)=>`<span class="${[1,2,3,4,5,8,9,10,11].includes(i)?'on':''}">${m}</span>`).join('')}</div><p class="legend">Azul = dentro de los períodos ordinarios. Puede haber sesiones extraordinarias en los términos del artículo 27.2.</p></div>`;
const investiture=()=>`<div class="visual"><h3>La secuencia de investidura · Art. 32</h3><div class="steps"><div class="step"><b>1.ª convocatoria</b><small>Mayoría absoluta</small></div><div class="step"><b>≥ 48 horas</b><small>Entre convocatorias</small></div><div class="step"><b>Posteriores</b><small>Mayoría simple</small></div></div><p class="timeline-note"><b>Reloj de 2 meses:</b> comienza al constituirse la Junta. Si no hay elegido → disolución y nuevas elecciones.</p></div>`;
const confidence=()=>`<div class="table-wrap"><table class="comparison"><caption>Confianza y censura · Art. 35</caption><thead><tr><th>Regla</th><th>Cuestión de confianza</th><th>Moción de censura</th></tr></thead><tbody><tr><th>Inicia</th><td>Presidente, tras deliberación del Consejo</td><td>Al menos 15 % de los diputados</td></tr><tr><th>Contenido</th><td>Programa o declaración de política general</td><td>Candidato alternativo obligatorio</td></tr><tr><th>Mayoría</th><td><b>Simple</b></td><td><b>Absoluta</b></td></tr><tr><th>Si cae el Presidente</th><td>Dimite; convocatoria del pleno en máximo 15 días para elegir sucesor; sin disolución</td><td>Dimite; candidato de la moción investido y nombrado por el Rey</td></tr><tr><th>Plazos propios</th><td>No puede plantearse con censura en trámite</td><td>5 días hasta votar; alternativas en los 2 primeros; firmantes esperan 1 año si fracasa</td></tr></tbody></table></div>`;
function renderStudy(){let previous='';$('#toc').innerHTML='<h2>Tu ruta de estudio</h2>'+blocks.map((b,i)=>{let header=b.group!==previous?`<div class="toc-section">${groups[b.group]}</div>`:'';previous=b.group;return header+`<a href="#block-${b.id}"><span class="number">${b.group==='anexo'?'+':String(i+1).padStart(2,'0')}</span><span>${esc(b.title)}</span><span class="done-dot" data-dot="${b.id}"></span></a>`}).join('');$('#studyBlocks').innerHTML=blocks.map(b=>`<article class="block ${b.group==='anexo'?'extra':''}" id="block-${b.id}" data-block="${b.id}"><div class="block-heading"><div>${b.group==='anexo'?'<span class="extra-label">Complemento · Título II bis</span>':`<span class="ref">ART${b.articles.length>1?'S':''}. ${b.articles.join(' · ')}</span>`}<h2>${esc(b.title)}</h2></div>${b.group==='anexo'?'':`<button class="mark" data-done="${b.id}" aria-pressed="false">Marcar dominado</button>`}</div><p class="lead">${b.lead}</p><ul class="points">${b.points.map(p=>'<li>'+p+'</li>').join('')}</ul>${b.visual==='calendar'?calendar():b.visual==='investiture'?investiture():b.visual==='confidence'?confidence():''}<p class="trap"><b>Fíjate en la diferencia.</b> ${b.trap}</p><details class="recall"><summary>Compruébate <span class="recall-question">${b.prompt}</span></summary><p>${b.answer}</p></details>${b.articles.map(ref=>`<details class="literal" id="literal-${ref.replaceAll(' ','-')}"><summary>Leer el artículo ${ref} completo</summary><div class="literal-body">${articles[ref].paragraphs.map(p=>'<p>'+esc(p)+'</p>').join('')}<p class="official"><a href="https://www.boe.es/buscar/act.php?id=BOE-A-1982-634#${articles[ref].anchor}" target="_blank" rel="noopener noreferrer">Consultar artículo ${ref} en el BOE ↗</a></p></div></details>`).join('')}<div class="source-row"><span>Tu PDF:</span>${b.pages.map(p=>`<button data-page="${p}">Pág. ${p}</button>`).join('')}</div></article>`).join('');updateProgress();filterStudy()}
function updateProgress(){const n=saved.done.length;$('#progressText').textContent=n+' / 13';$('#studyProgress').value=n;$$('[data-done]').forEach(el=>{const done=saved.done.includes(el.dataset.done);el.setAttribute('aria-pressed',done);el.textContent=done?'✓ Dominado':'Marcar dominado'});$$('[data-dot]').forEach(el=>el.textContent=saved.done.includes(el.dataset.dot)?'✓':'')}
function filterStudy(){let term=norm($('#studySearch').value.trim());term=term.replace(/^art(?:iculo|iculos|\.)?\s+/,'');const group=$('#studyGroup').value;let count=0;blocks.forEach(b=>{const hay=norm([b.title,...b.articles.map(n=>'articulo '+n),plain(b.lead),...b.points.map(plain),b.trap,...b.articles.flatMap(n=>articles[n].paragraphs)].join(' '));const isArticle=/^\d+(?:\s+(?:bis|ter|quater))?$/.test(term);const matches=!term||(isArticle?b.articles.includes(term):hay.includes(term));const show=(group==='all'||b.group===group)&&matches;$('#block-'+b.id).hidden=!show;if(show)count++});$('#resultCount').textContent=count===14?'13 bloques del apartado + 1 complemento de órganos auxiliares':count===1?'1 bloque encontrado':count+' bloques encontrados';$('#studyEmpty').hidden=!!count}
function openArticle(ref){const b=blocks.find(b=>b.articles.includes(ref));if(!b)return;$('#studyGroup').value='all';$('#studySearch').value='';filterStudy();showTab('study');const el=$('#literal-'+ref.replaceAll(' ','-'));el.open=true;el.querySelector('summary').focus({preventScroll:true});el.scrollIntoView({block:'start'})}
function renderQuick(){const facts=[['7/1981','Ley orgánica de 30 de diciembre','1'],['35–45','Intervalo estatutario de miembros de la Junta','25'],['4 años','Duración ordinaria de la legislatura','25'],['4.º domingo','De mayo: elecciones cada cuatro años','25'],['15 días','Para convocar la Junta electa desde las elecciones','25'],['¼','De miembros para pedir sesión extraordinaria','27'],['15 días','Para publicar leyes en BOPA desde su aprobación','31'],['48 horas','Mínimo entre convocatorias de investidura','32'],['2 meses','Sin elegido desde la constitución → disolución','32'],['15 %','Mínimo de proponentes de la censura','35'],['5 / 2 días','Espera para votar / primeros días para alternativas','35'],['1 año','Espera de firmantes si fracasa la censura','35']];$('#quickContent').innerHTML=`<div class="quick-grid">${facts.map(f=>`<div class="quick-card"><span class="value">${f[0]}</span><p>${f[1]}</p>${f[0]==='7/1981'?'<span class="small">Identificación de la norma</span>':refButton(f[2])}</div>`).join('')}</div><div class="quick-note"><p><b>El tercer “15 días”:</b> tras negar la confianza, el Presidente de la Junta convoca el pleno para elegir sucesor en <b>máximo 15 días</b>, sin disolverla. ${refButton('35')}</p></div>${confidence()}<div class="table-wrap"><table class="comparison"><caption>Mayorías: conserva el sujeto y la regla</caption><thead><tr><th>Tipo</th><th>Se exige para…</th><th>Artículo</th></tr></thead><tbody><tr><th>Absoluta</th><td>Ley electoral y reforma; Reglamento de la Junta y reforma; primera investidura; ley reguladora del Presidente; ley del Consejo; censura</td><td>25.2 · 28.1 · 32 · 33.2 · 35.2</td></tr><tr><th>Simple</th><td>Investiduras posteriores; cuestión de confianza</td><td>32.1 · 35.1</td></tr><tr><th>Mayoría de los miembros</th><td>Asistencia para deliberar y acordar; ley sobre responsabilidad y relaciones Junta–Consejo</td><td>27.4 · 34.2</td></tr><tr><th>Mayoría de los presentes</th><td>Regla general de adopción de acuerdos, salvo mayoría más cualificada</td><td>27.4</td></tr></tbody></table></div><div class="visual"><h3>Ensaya las cifras de una Cámara</h3><div class="majority-form"><label for="memberCount">Número de miembros (35–45)</label><input type="number" min="35" max="45" step="1" id="memberCount" value="45"></div><div class="math-results" id="mathResults" aria-live="polite"></div><p class="legend">Ejercicio de cálculo dentro del intervalo estatutario. La mayoría absoluta supera la mitad; los mínimos del 15 % y de una cuarta parte se redondean al entero superior.</p></div>${calendar()}${investiture()}<div class="quick-note"><p><b>Dos disoluciones, un mismo límite:</b> la anticipada del art. 25 y la del bloqueo de investidura del art. 32 dejan a la nueva Junta solo el tiempo restante de la legislatura originaria. <b>Negar la confianza no disuelve la Junta.</b></p></div>`;$('#memberCount').addEventListener('input',updateMath);updateMath()}
function updateMath(){const n=Number($('#memberCount').value);$('#mathResults').innerHTML=Number.isInteger(n)&&n>=35&&n<=45?`<span><b>${Math.floor(n/2)+1}</b>Mayoría absoluta</span><span><b>${Math.ceil(n*.15)}</b>Proponentes de censura</span><span><b>${Math.ceil(n/4)}</b>¼ de la Cámara</span>`:'<span>Introduce un número entero entre 35 y 45.</span>'}
let flashQueue=[],flashIndex=0,flashRevealed=false;function due(c){const r=saved.srs[c.id];return !r||!Number.isFinite(r.due)||r.due<=Date.now()}
function resetFlash(mix=false){const g=$('#flashGroup').value;const all=cards.filter(c=>g==='all'||c.group===g);flashQueue=all.filter(c=>!$('#onlyDue').checked||due(c));if(mix)flashQueue=shuffled(flashQueue);flashIndex=0;flashRevealed=false;renderFlash()}
function renderFlash(){const g=$('#flashGroup').value;const pool=cards.filter(c=>g==='all'||c.group===g);$('#flashDue').textContent='Pendientes: '+pool.filter(due).length;if(flashIndex>=flashQueue.length){$('#flashPosition').textContent=flashQueue.length?'Sesión terminada':'Sin tarjetas para este filtro';$('#flashContent').innerHTML=`<div class="session-end"><h3>${flashQueue.length?'Buen momento para hacer una pausa':'Todo al día en este apartado'}</h3><p>${flashQueue.length?'Tarjetas revisadas: '+flashQueue.length+'. Las que cuestan siguen pendientes para hoy.':'Puedes desactivar «Solo pendientes» para repasar también las programadas.'}</p><button class="primary" id="restartFlash">Revisar pendientes</button></div>`;$('#restartFlash').onclick=()=>{$('#onlyDue').checked=true;resetFlash(true)};return}const c=flashQueue[flashIndex];$('#flashPosition').textContent='Tarjeta '+(flashIndex+1)+' de '+flashQueue.length;$('#flashContent').innerHTML=`<div class="flash"><span class="ref">${groups[c.group]} · Art. ${c.ref}</span><h3>${esc(c.q)}</h3><button class="primary" id="revealFlash"${flashRevealed?' hidden':''}>Mostrar respuesta</button><div id="flashAnswer"${flashRevealed?'':' hidden'}><div class="flash-answer">${esc(c.a)}<div style="margin-top:10px">${refButton(c.ref,'Leer el artículo')}</div></div><div class="ratings"><button id="flashAgain">Me cuesta · hoy</button><button class="primary" id="flashKnown">Lo recuerdo</button></div></div></div>`;$('#revealFlash').onclick=()=>{flashRevealed=true;$('#revealFlash').hidden=true;$('#flashAnswer').hidden=false;$('#flashAgain').focus()};$('#flashAgain').onclick=()=>rateCard(false);$('#flashKnown').onclick=()=>rateCard(true)}
function rateCard(known){const c=flashQueue[flashIndex];if(!c||!flashRevealed)return;const previous=saved.srs[c.id];const box=known?Math.min((Number.isInteger(previous?.box)?previous.box:0)+1,5):0;const days=known?[1,3,7,14,30][box-1]:0;saved.srs[c.id]={box,due:Date.now()+days*86400000};persist();toast(known?'Próximo repaso: '+days+(days===1?' día.':' días.'):'Sigue pendiente para hoy.');flashIndex++;flashRevealed=false;renderFlash()}
let quizQueue=[],quizIndex=0,quizScore=0,quizWrong=[],quizAnswered=false;
function updateQuizSetup(){const g=$('#quizGroup').value;const amount=questions.filter(q=>g==='all'||q[0]===g).length;$('#quizAvailable').textContent=amount+' preguntas · orden aleatorio · corrección después de cada respuesta';$('#repeatWrong').hidden=!saved.lastWrong.length;$('#quizHistory').textContent=saved.lastResult?'Último test terminado: '+saved.lastResult.score+' / '+saved.lastResult.total+' · Fallos pendientes: '+saved.lastWrong.length+'.':''}
function startQuiz(failures=false){const g=$('#quizGroup').value;quizQueue=shuffled(failures?saved.lastWrong:questions.map((_,i)=>i).filter(i=>g==='all'||questions[i][0]===g));if(!quizQueue.length)return;quizIndex=0;quizScore=0;quizWrong=[];quizAnswered=false;$('#quizSetup').hidden=true;$('#quizContent').hidden=false;renderQuestion()}
function renderQuestion(){if(quizIndex>=quizQueue.length){finishQuiz();return}quizAnswered=false;const q=questions[quizQueue[quizIndex]];$('#quizContent').innerHTML=`<div class="practice-top"><span>Pregunta ${quizIndex+1} de ${quizQueue.length}</span><span>${quizScore} aciertos</span></div><article class="quiz-card"><span class="ref">${groups[q[0]]}</span><h3>${esc(q[1])}</h3><div class="answers">${q[2].map((a,i)=>`<button class="answer" data-answer="${i}"><span class="letter" aria-hidden="true">${'ABCD'[i]}</span><span>${esc(a)}</span></button>`).join('')}</div><div class="feedback" id="feedback" role="status" hidden></div><div class="next-row"><button class="primary" id="nextQuestion" hidden>${quizIndex+1===quizQueue.length?'Ver resultado':'Siguiente pregunta →'}</button></div></article>`;$$('[data-answer]').forEach(b=>b.onclick=()=>answerQuestion(Number(b.dataset.answer)));$('#nextQuestion').onclick=()=>{quizIndex++;renderQuestion()}}
function answerQuestion(chosen){if(quizAnswered)return;quizAnswered=true;const id=quizQueue[quizIndex],q=questions[id],right=chosen===q[3];if(right)quizScore++;else quizWrong.push(id);$$('[data-answer]').forEach(b=>{b.disabled=true;if(Number(b.dataset.answer)===q[3])b.classList.add('right');else if(Number(b.dataset.answer)===chosen)b.classList.add('wrong')});$('#feedback').hidden=false;$('#feedback').innerHTML=`<b>${right?'✓ Correcto':'Esta conviene repasarla'}</b><p>${right?'':'Respuesta correcta: <strong>'+esc(q[2][q[3]])+'</strong>. '}${esc(q[4])}</p>${refButton(q[5],'Repasar el artículo '+q[5])}`;$('#nextQuestion').hidden=false;$('#nextQuestion').focus({preventScroll:true})}
function finishQuiz(){saved.lastWrong=[...quizWrong];saved.lastResult={score:quizScore,total:quizQueue.length};persist();updateQuizSetup();$('#quizContent').innerHTML=`<div class="session-end"><p class="eyebrow">Test terminado</p><h3>${quizWrong.length?'Ya sabes qué merece otra vuelta':'Has resuelto todas las preguntas'}</h3><span class="score">${quizScore} / ${quizQueue.length}</span><p>${quizWrong.length?'Repasa los artículos de los fallos y vuelve a intentarlo.':'Puedes cambiar de apartado o volver a las tarjetas.'}</p>${quizWrong.length?`<div class="wrong-list">${quizWrong.map(i=>`<button data-article="${questions[i][5]}">${esc(questions[i][1])} · Art. ${questions[i][5]}</button>`).join('')}</div><button class="primary" id="retrySession">Repetir estos fallos</button> `:''}<button id="newQuiz">Elegir otro test</button></div>`;if($('#retrySession'))$('#retrySession').onclick=()=>startQuiz(true);$('#newQuiz').onclick=()=>{$('#quizSetup').hidden=false;$('#quizContent').hidden=true}}
function renderStories(){$('#storyContent').innerHTML=stories.map(s=>`<article class="story"><span class="ref">${esc(s.ref)}</span><h3>${esc(s.title)}</h3><div class="scene" aria-hidden="true">${s.scene}</div><div class="pegs">${s.pegs.map(p=>'<span class="peg">'+esc(p)+'</span>').join('')}</div><p>${esc(s.text)}</p><p class="decode"><b>Decodifica.</b> ${esc(s.key)}</p><details class="recall"><summary>${esc(s.ask)}</summary><p>${esc(s.answer)}</p></details></article>`).join('')}
function renderSources(){$('#gallery').innerHTML=sourcePages.map((p,i)=>`<button class="page-thumb" data-page="${p}"><img src="estatuto-assets/pagina-${p}.jpg" loading="lazy" alt="Vista de la página ${p} del PDF"><b>Página ${p}</b><small>${pageLabels[i]}</small></button>`).join('')}
let currentPage=0;function showPage(p){currentPage=sourcePages.indexOf(p);if(currentPage<0)return;updatePage();if(!$('#pageDialog').open)$('#pageDialog').showModal()}
function updatePage(){const p=sourcePages[currentPage];$('#pageTitle').textContent='PDF · Página '+p+' / '+pageLabels[currentPage];$('#pageImage').src='estatuto-assets/pagina-'+p+'.jpg';$('#pageImage').alt='Página '+p+' del documento LEGISLACION BOMBEROS (2).pdf';$('#fullPageLink').href=$('#pageImage').src;$('#prevPage').disabled=currentPage===0;$('#nextPage').disabled=currentPage===sourcePages.length-1;$('#pageDialog').scrollTop=0}
function showTab(id){$$('.tab').forEach(t=>{const selected=t.dataset.tab===id;t.setAttribute('aria-selected',selected);t.tabIndex=selected?0:-1});$$('.panel').forEach(p=>p.hidden=p.id!==id);if(id==='flashcards'&&!flashQueue.length)resetFlash();if(id==='quiz')updateQuizSetup();$('#main').scrollIntoView({block:'start',behavior:'instant'})}
$$('.tab').forEach(t=>{t.onclick=()=>showTab(t.dataset.tab);t.onkeydown=e=>{const tabs=$$('.tab');let i=tabs.indexOf(t);if(e.key==='ArrowRight')i=(i+1)%tabs.length;else if(e.key==='ArrowLeft')i=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else return;e.preventDefault();tabs[i].focus();showTab(tabs[i].dataset.tab)}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.done){const id=b.dataset.done;saved.done=saved.done.includes(id)?saved.done.filter(x=>x!==id):[...saved.done,id];persist();updateProgress()}if(b.dataset.page)showPage(Number(b.dataset.page));if(b.dataset.article)openArticle(b.dataset.article)});
$('#toc').addEventListener('click',e=>{if(e.target.closest('a')){$('#studyGroup').value='all';$('#studySearch').value='';filterStudy()}});$('#studySearch').addEventListener('input',filterStudy);$('#studyGroup').addEventListener('change',filterStudy);$('#clearSearch').onclick=()=>{$('#studyGroup').value='all';$('#studySearch').value='';filterStudy();$('#studySearch').focus()};$('#flashGroup').onchange=()=>resetFlash();$('#onlyDue').onchange=()=>resetFlash();$('#shuffleCards').onclick=()=>resetFlash(true);$('#quizGroup').onchange=updateQuizSetup;$('#startQuiz').onclick=()=>startQuiz();$('#repeatWrong').onclick=()=>startQuiz(true);$('#printButton').onclick=()=>window.print();$('#closePage').onclick=()=>$('#pageDialog').close();$('#prevPage').onclick=()=>{if(currentPage>0){currentPage--;updatePage()}};$('#nextPage').onclick=()=>{if(currentPage<sourcePages.length-1){currentPage++;updatePage()}};
renderStudy();renderQuick();renderStories();renderSources();resetFlash();updateQuizSetup();persist();
